#include "channel.h"
#include "math3d.h"
#include "beam.h"
#include <stdio.h>
#include <string.h>
#include <math.h>
static Vec3 array_position(const Node *n,const NodePosition *p,const ArrayMount *a){return add(p->position,apply(node_rot_ecef(n->attitude,p->geodetic),a->offset));}
static float array_gain_amplitude(const Node *n,const NodePosition *p,const ArrayMount *a,Vec3 direction){Mat3 r=array_rot_ecef(n->attitude,p->geodetic,a->initial_attitude);Attitude scan={n->beam_direction.azimuth,n->beam_direction.elevation,0};r=compose_rot(r,scan_rot(scan));Vec3 local=apply(mat3_transpose(r),direction);float theta=deg(atan2(local.z,hypot(local.x,local.y))),phi=deg(atan2(local.y,fabs(local.x)));return beam_gain(&g_beam_cache,a->beam_table_index,theta,phi);}
ChannelResult channel(const SimConfig *c,const Node *tx,const NodePosition *tp,const Node *rx,const NodePosition *rp,const ArrayMount *ta,const ArrayMount *ra,double t){ChannelResult o;memset(&o,0,sizeof(o));o.index=LINK_INDEX_INVALID;o.t=t;o.txid=tx?tx->id:-1;o.rxid=rx?rx->id:-1;o.txaid=ta?ta->id:-1;o.rxaid=ra?ra->id:-1;if(!c||!tx||!rx||!tp||!rp||!ta||!ra||!tx->enabled||!rx->enabled||!ta->enabled||!ra->enabled||tx->tr_state!=NODE_TX||rx->tr_state!=NODE_RX)return o;ptrdiff_t ts=ta-tx->arrays,rs=ra-rx->arrays;if(ts<0||ts>=(ptrdiff_t)tx->array_count||rs<0||rs>=(ptrdiff_t)rx->array_count||!LinkIndex_Encode((uint8_t)tx->id,(uint8_t)rx->id,(uint8_t)ts,(uint8_t)rs,&o.index))return o;if(tx->tx_array_id>=0&&ta->id!=tx->tx_array_id)return o;if(fabsf(ta->beam_config.frequency_mhz-ra->beam_config.frequency_mhz)>1e-6f)return o;double fc=ta->beam_config.frequency_mhz*1e6;Vec3 delta=sub(array_position(rx,rp,ra),array_position(tx,tp,ta));o.d=norm(delta);if(o.d<1e-6)return o;Vec3 u=scale(delta,1.0/o.d);o.tau=o.d/C0;o.vr=dot(sub(rx->velocity,tx->velocity),u);o.fd=-o.vr*fc/C0;o.fspl=20.0*log10(4.0*PI*o.d*fc/C0);float atx=array_gain_amplitude(tx,tp,ta,u),arx=array_gain_amplitude(rx,rp,ra,scale(u,-1));if(atx<=0||arx<=0)return o;o.gtx_db=20*log10f(atx);o.grx_db=20*log10f(arx);o.element_tx_power_dbm=ta->element_tx_power_dbm;float ntx=(float)ta->beam_config.num_h*ta->beam_config.num_v;o.pr_dbm=o.element_tx_power_dbm+10*log10f(ntx)+o.gtx_db+o.grx_db-(float)o.fspl;double lambda=C0/fc,amp=sqrt(ntx)*atx*arx*lambda/(4*PI*o.d),phase=-2*PI*fc*o.tau;o.h.re=(float)(amp*cos(phase));o.h.im=(float)(amp*sin(phase));o.valid=1;return o;}
void print_channel(ChannelResult r){if(!r.valid){printf(" H%d%d array %d->%d unavailable\n",r.txid,r.rxid,r.txaid,r.rxaid);return;}printf(" H%d%d array %d->%d [index=%u] d=%.3f m tau=%.4e s vr=%.3f m/s fd=%.3f Hz FSPL=%.2f dB Gtx=%.2f dB Grx=%.2f dB Pelem=%.2f dBm Pr=%.2f dBm h=(%+.4e,%+.4e)\n",r.txid,r.rxid,r.txaid,r.rxaid,(unsigned)r.index,r.d,r.tau,r.vr,r.fd,r.fspl,r.gtx_db,r.grx_db,r.element_tx_power_dbm,r.pr_dbm,r.h.re,r.h.im);}
